import math

def sequence_ratio(new_logp, old_logp, mask):
    length = sum(mask)
    if length == 0:
        raise ValueError('유효 토큰이 없습니다.')
    log_ratio = sum((n - o) * m for n, o, m in zip(new_logp, old_logp, mask))
    return math.exp(log_ratio / length)

