def clipped_objective(ratios, advantages, epsilon=0.2):
    terms = []
    for r, a in zip(ratios, advantages):
        clipped = min(max(r, 1 - epsilon), 1 + epsilon)
        terms.append(min(r * a, clipped * a))
    return sum(terms) / len(terms)
